import React, { useEffect, useMemo, useRef, useState } from "react";
import app from "@/store/app";
import { IfrmaeAppProps, IfrmaeWindowProps } from "@/types/iframe";
import file from "@/store/file";
import language from '@/store/language'
import pageStore from "@/store/page";
import Store from './store';
import styles from './index.module.less';
import AppTheme from "@/components/Settings/theme";
import { moduleStore } from "react-converter-code";
import { useObserver } from "mobx-react-lite";
import { Button, Divider, Popover, Space, Tree } from "@arco-design/web-react";
import i18next from "i18next";
import { MobileKey } from "@/types/mobile";
import userStore from "@/store/userStore";
import pluginsStore from '@/store/plugins';


interface AppIframeProps {

}

const win: IfrmaeWindowProps = window as any;
const AppIframe = () => {

    const [store] = useState(() => new Store());

    useEffect(() => {

        const handleMessage = (event) => {
            if(typeof event.data == "object"){
                const { key } = event.data;
                switch(key){
                    case MobileKey.IframeAppReady:
                        // 接受状态信息
                        store.setIsFrameReady(true);
                    break;
                }
            }
        };
    
        window.addEventListener('message', handleMessage);
    
        return () => {
            window.removeEventListener('message', handleMessage);
        };
    }, []);


    return useObserver(() => {
        useEffect(() => {
            const iframe = store.iframeRef.current;
            if(iframe){
                Object.assign(
                    iframe.contentWindow,
                    {
                        iframeApp: true,
                        userStore,
                        moduleStore,
                        fileStore: file,
                        app: app,
                        language,
                        pageStore: pageStore,
                        pluginsStore,
                    } as IfrmaeAppProps
                )
            }
        },[store.isReady])


        useEffect(() => {
            const iframeWindow: any = store.iframeRef.current?.contentWindow;
            if(iframeWindow){
                const updatePathname = () => {
                    const path = iframeWindow.location.hash;
                    store.setPathname(path)
                    console.log('path', path.startsWith('#/admin'), win.dev)
                    if(path.startsWith('#/admin')){
                        if(win.dev){
                            win.dev.autoLogin()
                        }
                    }
                }
                updatePathname();
                iframeWindow.addEventListener('hashchange', function() {
                    updatePathname()
                });
            }
        },[store.isReady])

        const { login_path, admin_path } = app.extraInfo.configuration;

        return (
            <div className="h-full flex flex-col">
                {store.isFrameReady && (
                    <div className={styles.header}>
                        <Space>
                            <div>
                                切换路由
                                <Popover
                                    position='bl'
                                    trigger="click"
                                    content={(
                                        <div className="min-w-80 h-80 overflow-y-auto">
                                            <Tree
                                                blockNode
                                                className="w-full"
                                                autoExpandParent
                                                fieldNames={{
                                                    key: "path",
                                                    title: "name"
                                                }}
                                                defaultSelectedKeys={[store.pathname]}
                                                onSelect={(keys, extra) => {
                                                    const { dataRef: item }: any = extra.node.props
                                                    if(win.utils){
                                                        win.utils.history.push(item.path)
                                                    }
                                                }}
                                                treeData={win.dev? win.dev.routes : []}
                                                renderTitle={({ title, dataRef, ...props }) => {
                                                    return `${i18next.t(title as string)}(${dataRef.path})`
                                                }}
                                            />
                                            <Divider style={{ margin: "0 20px" }}>后台路由</Divider>
                                            <Tree
                                                blockNode
                                                autoExpandParent
                                                fieldNames={{
                                                    key: "path",
                                                    title: "name"
                                                }}
                                                defaultSelectedKeys={[store.pathname.replace('/admin', '')]}
                                                onSelect={(keys, extra) => {
                                                    const { dataRef: item }: any = extra.node.props
                                                    if(win.utils){
                                                        const { history } = win.utils
                                                        if(item.path == login_path){
                                                            history.push(`${keys[0]}`);
                                                        }else {
                                                            history.push(`${admin_path}${keys[0]}`);
                                                        }
                                                    }
                                                }}
                                                treeData={[
                                                    {
                                                        path: login_path,
                                                        name: "登陆页面",
                                                    },
                                                    ...win.dev.adminMenu,
                                                ]}
                                                renderTitle={({ title, dataRef, ...props }) => {
                                                    return `${i18next.t(title as string)}(${dataRef.path})`
                                                }}
                                            />
                                        </div>
                                    )}
                                >
                                    <Button type="text" size="small" >
                                        URL：{store.pathname}
                                    </Button>
                                </Popover>
                            </div>
                            <Popover
                                position='bl'
                                trigger="click"
                                style={{ maxWidth: 900 }}
                                content={(
                                    <div style={{ width: 800 }}>
                                        <AppTheme />
                                    </div>
                                )}
                            >
                                <Button type="default" size="small" >
                                    切换主题
                                </Button>
                            </Popover>
                        </Space>
                    </div>
                )}
                {store.isReady? (
                    <iframe 
                        className="w-full grow"
                        src={'/'}
                        ref={store.iframeRef}
                    ></iframe>
                ): null}
            </div>
        )
    })
}


export default AppIframe;